import type * as Kit from '@sveltejs/kit';

type Expand<T> = T extends infer O ? { [K in keyof O]: O[K] } : never;
type MatcherParam<M> = M extends (param : string) => param is (infer U extends string) ? U : string;
type RouteParams = {  };
type RouteId = '/';
type MaybeWithVoid<T> = {} extends T ? T | void : T;
export type RequiredKeys<T> = { [K in keyof T]-?: {} extends { [P in K]: T[K] } ? never : K; }[keyof T];
type OutputDataShape<T> = MaybeWithVoid<Omit<App.PageData, RequiredKeys<T>> & Partial<Pick<App.PageData, keyof T & keyof App.PageData>> & Record<string, any>>
type EnsureDefined<T> = T extends null | undefined ? {} : T;
type OptionalUnion<U extends Record<string, any>, A extends keyof U = U extends U ? keyof U : never> = U extends unknown ? { [P in Exclude<A, keyof U>]?: never } & U : never;
export type Snapshot<T = any> = Kit.Snapshot<T>;
type LayoutRouteId = RouteId | "/(content)" | "/(content)/[slug]" | "/(content)/about" | "/(content)/archive" | "/(content)/contact" | "/(content)/disclaimer" | "/(content)/dotadle-answer-today" | "/(content)/editorial-policy" | "/(content)/guides" | "/(content)/loldle-answer-today" | "/(content)/narutodle-answer-today" | "/(content)/onepiecedle-answer-today" | "/(content)/pokedle-answer-today" | "/(content)/privacy-policy" | "/(content)/smashdle-answer-today" | "/(content)/solver" | "/(content)/terms-of-service" | "/(content)/today" | "/(interactive)/[variant=wordlebotVariant]-solver" | "/(interactive)/[wordLength=wordlebotLength]-letter-wordle-solver" | "/(interactive)/all-wordle-solver" | "/(interactive)/betweenle" | "/(interactive)/betweenle-answer-today" | "/(interactive)/betweenle-solver" | "/(interactive)/boggle-solver" | "/(interactive)/canuckle" | "/(interactive)/canuckle-answer-today" | "/(interactive)/canuckle-archive" | "/(interactive)/colordle-answer-today" | "/(interactive)/colordle-archive" | "/(interactive)/colordle-solver" | "/(interactive)/colorfle-answer-today" | "/(interactive)/colorfle-archive" | "/(interactive)/colorfle-solver" | "/(interactive)/contexto-answer-today" | "/(interactive)/contexto-archive" | "/(interactive)/countryle-answer-today" | "/(interactive)/countryle-archive" | "/(interactive)/countryle-solver" | "/(interactive)/dotadle-solver" | "/(interactive)/framed-answer-today" | "/(interactive)/framed-archive" | "/(interactive)/globle-answer-today" | "/(interactive)/globle-archive" | "/(interactive)/hangman-solver" | "/(interactive)/kanoodle-solver" | "/(interactive)/light-out-solver" | "/(interactive)/loldle-solver" | "/(interactive)/minesweeper-solver" | "/(interactive)/narutodle-solver" | "/(interactive)/nerdle-answer-today" | "/(interactive)/nerdle-archive" | "/(interactive)/nerdle-solver" | "/(interactive)/onepiecedle-solver" | "/(interactive)/onepiedle-solver" | "/(interactive)/phoodle-answer-today" | "/(interactive)/phoodle-archive" | "/(interactive)/phoodle-solver" | "/(interactive)/phrazle-answer-today" | "/(interactive)/phrazle-archive" | "/(interactive)/pokedle-solver" | "/(interactive)/quordle-answer-today" | "/(interactive)/quordle-archive" | "/(interactive)/searchle-answer-today" | "/(interactive)/searchle-archive" | "/(interactive)/searchle-solver" | "/(interactive)/semantle-answer-today" | "/(interactive)/semantle-archive" | "/(interactive)/smashdle-solver" | "/(interactive)/soundmap-solver" | "/(interactive)/sportle-answer-today" | "/(interactive)/sportle-archive" | "/(interactive)/sportle-solver" | "/(interactive)/spotle-answer-today" | "/(interactive)/spotle-archive" | "/(interactive)/spotle-solver" | "/(interactive)/squaredle-solver" | "/(interactive)/waffle-answer-today" | "/(interactive)/waffle-archive" | "/(interactive)/waffle-solver" | "/(interactive)/weaver-solver" | "/(interactive)/word-ladder-solver" | "/(interactive)/wordle-analyzer" | "/(interactive)/wordle-answer-archive" | "/(interactive)/wordle-answer-today" | "/(interactive)/wordle-solver" | "/(interactive)/worgle-answer-today" | "/(interactive)/worgle-archive" | "/(interactive)/worldle-answer-today" | "/(interactive)/worldle-archive" | "/(interactive)/worldle-solver" | null
type LayoutParams = RouteParams & { slug?: string; variant?: MatcherParam<typeof import('../../../../src/params/wordlebotVariant.js').match>; wordLength?: MatcherParam<typeof import('../../../../src/params/wordlebotLength.js').match> }
type LayoutParentData = EnsureDefined<{}>;

export type LayoutServerData = null;
export type LayoutLoad<OutputData extends OutputDataShape<LayoutParentData> = OutputDataShape<LayoutParentData>> = Kit.Load<LayoutParams, LayoutServerData, LayoutParentData, OutputData, LayoutRouteId>;
export type LayoutLoadEvent = Parameters<LayoutLoad>[0];
export type LayoutData = Expand<Omit<LayoutParentData, keyof LayoutParentData & EnsureDefined<LayoutServerData>> & OptionalUnion<EnsureDefined<LayoutParentData & EnsureDefined<LayoutServerData>>>>;
export type LayoutProps = { params: LayoutParams; data: LayoutData; children: import("svelte").Snippet }